package com.projectseele.world;

import com.projectseele.entity.NervCarrierPlatformEntity;
import com.projectseele.world.NervFootGuideDockR52.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.phys.*;

/** A fixed Root turn station has its own actual actor and accepted clock.
 * It survives the original carrier's departure and never moves with it. */
public final class NervFootGuideStationR52 {
 public static String canonicalLeg(String id){return id.endsWith("/reverse")?id.substring(0,id.length()-8):id;}
 public static UUID proposedIdentityR52(long epoch,String leg){return UUID.nameUUIDFromBytes(("projectseele:r52:foot-station:"+epoch+":"+canonicalLeg(leg)).getBytes(StandardCharsets.UTF_8));}
 public static CompoundTag rawState(NervCarrierPlatformEntity e){return e.footGuideStationStateR52();}
 public static boolean declared(NervCarrierPlatformEntity e){var t=rawState(e);return t.getString("Source").equals(NervFootGuideDockR52.SOURCE_SHA)&&t.getString("GuideSource").equals(NervFootGuideRigR52.SOURCE_SHA)&&t.getLong("Epoch")>0&&t.contains("View")&&t.contains("Pose")&&e.getUUID().equals(proposedIdentityR52(t.getLong("Epoch"),t.getString("Leg")));}
 public static NervCarrierPlatformEntity controller(ServerLevel l,Spec spec){var actor=l.getEntity(proposedIdentityR52(spec.directory().epoch(),spec.leg().id()));if(!(actor instanceof NervCarrierPlatformEntity e)||!declared(e))return null;var t=rawState(e);return t.getString("Directory").equals(spec.directory().fingerprint())&&geometrySnapshot(t.getCompound("View")).equals(geometrySnapshot(NervFootGuideDockR52.snapshot(spec)))?e:null;}
 private static CompoundTag geometrySnapshot(CompoundTag input){var result=input.copy();result.put("Plug",NervAircraftFrameR52.encodeRigid(RigidTransform.identity()));return result;}
 public static ViewSpec view(NervCarrierPlatformEntity e){if(!declared(e))throw new IllegalStateException("Actual fixed station source required");return NervFootGuideDockR52.viewSpec(rawState(e).getCompound("View"));}
 public static StationPose currentPose(NervCarrierPlatformEntity e){if(!declared(e))throw new IllegalStateException("Actual fixed station sample required");return NervFootGuideDockR52.decodePose(rawState(e).getCompound("Pose"));}
 public static StationPose pose(NervCarrierPlatformEntity e,float partial){var t=rawState(e);var current=currentPose(e);if(!e.level().isClientSide)return current;double blend=net.minecraft.util.Mth.clamp(e.level().getGameTime()-t.getLong("At")+(double)partial,0,1);return NervFootGuideDockR52.interpolate(NervFootGuideDockR52.decodePose(t.getCompound("PreviousPose")),current,blend);}
 public static List<Piece> actualPartsR52(NervCarrierPlatformEntity e,float partial)throws IOException {return NervFootGuideDockR52.pieces(view(e),pose(e,partial));}
 public static List<NervFlightProofR52.ObstacleMesh> actualMeshesR52(NervCarrierPlatformEntity e)throws IOException {var out=new ArrayList<NervFlightProofR52.ObstacleMesh>();for(var p:actualPartsR52(e,1))out.add(new NervFlightProofR52.ObstacleMesh(p.mesh(),p.frame()));return List.copyOf(out);}
 public static AABB boundsR52(NervCarrierPlatformEntity e)throws IOException {AABB box=null;for(var p:actualPartsR52(e,1)){var b=p.mesh().envelope(p.frame(),p.frame());box=box==null?b:box.minmax(b);}return box;}
 public static final class DeclaredState {
  private final UUID actor;private final long at;private final CompoundTag before,next;
  private DeclaredState(NervCarrierPlatformEntity e,CompoundTag next){actor=e.getUUID();at=e.level().getGameTime();before=rawState(e);this.next=next.copy();}
  public boolean current(NervCarrierPlatformEntity e){return !e.level().isClientSide&&e.getUUID().equals(actor)&&e.level().getGameTime()==at&&rawState(e).equals(before);}
  public CompoundTag next(){return next.copy();}
 }
 public static boolean finiteFeetBear(ServerLevel l,Spec s)throws IOException {if(!NervFootGuideDockR52.foundationsBear(l,s))return false;for(var foot:NervFootGuideDockR52.feet(s)){var p=foot.centre();var face=new AABB(p.x-foot.halfX(),p.y-.001,p.z-foot.halfZ(),p.x+foot.halfX(),p.y,p.z+foot.halfZ());var tops=new ArrayList<AABB>();int y=net.minecraft.util.Mth.floor(p.y-.001);for(int x=net.minecraft.util.Mth.floor(face.minX);x<=net.minecraft.util.Mth.floor(face.maxX);x++)for(int z=net.minecraft.util.Mth.floor(face.minZ);z<=net.minecraft.util.Mth.floor(face.maxZ);z++){var at=new net.minecraft.core.BlockPos(x,y,z);if(!l.hasChunkAt(at))return false;for(var local:l.getBlockState(at).getCollisionShape(l,at).toAabbs()){var b=local.move(at);if(Math.abs(b.maxY-p.y)<.000003)tops.add(new AABB(b.minX,p.y-.001,b.minZ,b.maxX,p.y,b.maxZ));}}if(!NervAirspaceCoverageR52.covered(face,tops))return false;}return true;}
 public static String firstMissingFootR52(ServerLevel l,Spec s)throws IOException {for(var foot:NervFootGuideDockR52.feet(s))for(double x:new double[]{-foot.halfX(),0,foot.halfX()})for(double z:new double[]{-foot.halfZ(),0,foot.halfZ()}){var p=foot.centre().add(x,0,z);var at=net.minecraft.core.BlockPos.containing(p.add(0,-.001,0));if(!l.hasChunkAt(at))return "foot="+foot.name()+" point="+p+" block="+at.toShortString()+" expected_top="+p.y+" current=UNLOADED";var state=l.getBlockState(at);boolean bears=false;for(var local:state.getCollisionShape(l,at).toAabbs()){var b=local.move(at);if(p.x>=b.minX-1e-6&&p.x<=b.maxX+1e-6&&p.z>=b.minZ-1e-6&&p.z<=b.maxZ+1e-6&&Math.abs(b.maxY-p.y)<.000003)bears=true;}if(!bears)return "foot="+foot.name()+" point="+p+" block="+at.toShortString()+" expected_collision_top="+p.y+" current="+net.minecraft.commands.arguments.blocks.BlockStateParser.serialize(state)+" actual_shape="+state.getCollisionShape(l,at).toAabbs();}return finiteFeetBear(l,s)?"MATCH":"actual finite foot area is not fully covered by real native collision tops";}
 public static boolean declareNewR52(NervCarrierPlatformEntity e,Spec spec)throws IOException {if(!(e.level() instanceof ServerLevel l)||!rawState(e).isEmpty()||!e.hasDeclaredMachineFrameR52()||e.getUnitVariant()!=specVariant(spec)||!e.getUUID().equals(proposedIdentityR52(spec.directory().epoch(),spec.leg().id()))||!finiteFeetBear(l,spec))return false;var v=NervFootGuideDockR52.view(spec);var pose=new StationPose(0,1,1,0,0);var tag=new CompoundTag();tag.putString("Source",NervFootGuideDockR52.SOURCE_SHA);tag.putString("GuideSource",NervFootGuideRigR52.SOURCE_SHA);tag.putLong("Epoch",spec.directory().epoch());tag.putString("Directory",spec.directory().fingerprint());tag.putString("Leg",v.legId());tag.put("View",geometrySnapshot(NervFootGuideDockR52.snapshot(v)));tag.put("Pose",NervFootGuideDockR52.encodePose(pose));tag.put("PreviousPose",tag.getCompound("Pose").copy());tag.putLong("At",l.getGameTime());e.acceptFootGuideStationStateR52(new DeclaredState(e,tag));e.setBoundingBox(boundsR52(e));return declared(e);}
 private static int specVariant(Spec s){return NervFootGuideDockR52.view(s).variant();}
 private static boolean commit(ServerLevel l,NervCarrierPlatformEntity e,ViewSpec view,StationPose from,StationPose to){if(!declared(e)||!currentPose(e).equals(from)||!geometrySnapshot(rawState(e).getCompound("View")).equals(geometrySnapshot(NervFootGuideDockR52.snapshot(view))))return false;var tag=rawState(e);tag.put("PreviousPose",tag.getCompound("Pose").copy());tag.put("Pose",NervFootGuideDockR52.encodePose(to));tag.putLong("At",l.getGameTime());e.acceptFootGuideStationStateR52(new DeclaredState(e,tag));try{e.setBoundingBox(boundsR52(e));}catch(IOException unavailable){throw new IllegalStateException("Accepted real station source vanished",unavailable);}return true;}
 public static boolean acceptStationStepR52(ServerLevel l,AcceptedStationStep proof){if(proof==null||!proof.current(l)||!(l.getEntity(proof.station()) instanceof NervCarrierPlatformEntity e))return false;return commit(l,e,proof.view(),proof.fromPose(),proof.toPose());}
 public static boolean acceptDockStepR52(ServerLevel l,AcceptedDockStep proof){if(proof==null||!proof.current(l)||!(l.getEntity(proof.station()) instanceof NervCarrierPlatformEntity e))return false;return commit(l,e,NervFootGuideDockR52.view(proof.spec()),NervFootGuideDockR52.stationPose(proof.spec(),proof.from()),NervFootGuideDockR52.stationPose(proof.spec(),proof.to()));}
 private NervFootGuideStationR52(){}
}
